# --- extrase de presă din albumul companiei (adăugate 21.10.2026) ---
QUOTES = {
 'clipe-de-luciditate-1997': [("Apariția nebunilor din <em>Clipe de luciditate</em> te duce cu gândul la nebunii din <em>Porunca a 7-a</em>, a lui Dario Fo, personaje care au momente de luciditate, în această viață în care omul se luptă ca să supraviețuiască, fiind adesea cei mai lucizi. Interpretarea artistică a fost interesantă, un spectacol cu o scenografie bine realizată, cu o mișcare scenică bogată. Un spectacol muncit, așa cum mărturisește coregraful Hugo Wolff: <em>Pentru acest spectacol s-a muncit șase luni.</em> Zbuciumul lor interior, transformat în mișcare și grație, fiecare simțire tradusă în unduiri și pași, fiind transpus direct spectatorilor, creează o comuniune, personaj – interpret.", "Liviu Pietraru, Rondul de Sibiu, 22 aprilie 1997")],
 'curtea-miracolelor': [("Destul de transparent, și cu atât mai gustat de public, întrebările, dramele și multiplele probleme ale vârstei tinere s-au făcut vizibile în spectacolul „Curtea Miracolelor”, realizând un periplu modern al vieții contemporane în care tânărul se regăsește destul de greu pe sine, iar pe îngerul său păzitor destul de rar…", "Victoria A.F., Monitorul de Brăila, iunie 2005"),
  ("Cei 10 membri ai trupei, împreună cu Hugo, au reușit să pună în scenă o poveste de dragoste imposibilă din sec. XIX, când diferența de rang social era un obstacol de netrecut pentru doi îndrăgostiți. Această poveste dintre un el și o ea este transferată în sec. XX, când această diferență de rang social nu mai contează, dar când un pericol mai mare amenință o relație. Este vorba de droguri, dansul tinerilor fiind un protest față de acest flagel.", "(A.C.) Monitorul de Brăila, 4–5 iunie 2005")],
 'adam-si-eva': [("Spectacolul de dans „Adam și Eva” aduce pe scenă pasiune, gelozie și frământări sufletești. Acesta este triunghiul sub care stă soarta celor șase cupluri care își vor spune povestea în ritmuri de dans contemporan, povestea lor de dragoste fiind marcată de violența în familie. Aceasta este una din problemele grave cu care se confruntă societatea, fiind și motivul pentru care „Adam și Eva” reprezintă un protest și o luptă a tinerilor împotriva violenței în familie. „Nu lăsați dragostea să moară”, acesta este mesajul pe care dansatorii de la MICROBIS vor să îl transmită. Spectacolul este a treia producție sută la sută realizată de Casa de Cultură a Studenților Sibiu.", "Alina Suciu, 24 ORE MUREȘENE, 26 noiembrie 2005")],
 'ultima-imbucatura-din-dragoste': [("Pornind de la scene istorice, Hugo Wolff, cel care semnează coregrafia acestui spectacol, a transpus în dans momente din istoria neagră a Europei. Compania de Dans MICROBIS prezintă o creație construită într-un „lagăr al morții”, o poveste de dragoste și ură istorisită prin dans și muzică. Compania de Dans MICROBIS susține și promovează cu preponderență dansul contemporan, propunându-și inițierea unor proiecte culturale de impact. Deși formată preponderent din studenți, Compania Microbis a reușit de-a lungul anilor să impresioneze prin producțiile coregrafice originale.", "Adevărul de seară, 4 octombrie 2011")],
 'hurem-conditia-umana': [("Spectacolul „HUREM – condiția umană” are ca și fir roșu ciclul vieții umane, fiecare etapă pe care o parcurgem fiind evident transpusă în discursul coregrafic. Cu o recuzită relativ simplă, dar cu o coregrafie ce presupune elemente extrem de variate și coerente de mișcare, coregraful Hugo Wolff reușește să evidențieze fiecare vârstă a omului, anulând tentația oricăror interpretări. Poveștile sunt istorisite prin dans, muzică, poezie și nu în ultimul rând de spațiul neconvențional ales pentru premiera spectacolului.", "Tribuna, 19 septembrie 2012 — „Hurem, o premieră dansantă”")],
}
